import { RouteParams } from './types';
import { WRAPPED_SOL_MINT } from '@kamino-finance/limo-sdk';
import { createAssociatedTokenAccountIdempotentInstruction, createAtaIdempotent } from '../utils';
import { RFQ_ROUTERS, RouterType, SUPPORTED_ROUTER_TYPES } from '../consts';
import Decimal from 'decimal.js';
import BN from 'bn.js';
import { AccountRole, Address, createNoopSigner, Instruction, TransactionSigner } from '@solana/kit';
import { TOKEN_PROGRAM_ADDRESS } from '@solana-program/token';
import { getTransferSolInstruction } from '@solana-program/system';
import {
  findAssociatedTokenPda,
  getCloseAccountInstruction,
  getSyncNativeInstruction,
} from '@solana-program/token-2022';
import { IRouterContext } from './RouterContext';

export async function wrapAndUnwrapSolIxs(params: RouteParams): Promise<{
  wrapIxs: Instruction[];
  unwrapIxs: Instruction[];
}> {
  let wrapIxs: Instruction[] = [];
  let unwrapIxs: Instruction[] = [];
  if (params.tokenIn === WRAPPED_SOL_MINT && params.wrapAndUnwrapSol) {
    const [wrapIxsResult, unwrapIxResult] = await Promise.all([
      wrapSolIxs(params, undefined, true),
      unwrapSolIx(params, undefined),
    ]);

    wrapIxs = wrapIxsResult;
    unwrapIxs = [unwrapIxResult];
  }

  if (params.tokenOut === WRAPPED_SOL_MINT && params.wrapAndUnwrapSol) {
    const [wrapIxsResult, unwrapIxResult] = await Promise.all([
      wrapSolIxs(params, undefined, false),
      unwrapSolIx(params, params.destinationTokenAccount),
    ]);
    wrapIxs = wrapIxsResult;
    unwrapIxs = [unwrapIxResult];
  }
  return { wrapIxs, unwrapIxs };
}

export async function unwrapSolIx(params: RouteParams, wsolTa: Address | undefined): Promise<Instruction> {
  let wsolAta = wsolTa;
  if (!wsolAta) {
    const [associatedTokenAddress] = await findAssociatedTokenPda({
      mint: WRAPPED_SOL_MINT,
      owner: params.executor,
      tokenProgram: TOKEN_PROGRAM_ADDRESS,
    });
    wsolAta = associatedTokenAddress;
  }
  const unwrapSolIx = getCloseAccountInstruction(
    {
      account: wsolAta,
      destination: params.executor,
      owner: params.executor,
      multiSigners: [],
    },
    { programAddress: TOKEN_PROGRAM_ADDRESS },
  );
  return unwrapSolIx;
}

export async function wrapSolIxs(
  params: RouteParams,
  wsolTa: Address | undefined,
  withDeposit: boolean,
): Promise<Instruction[]> {
  const ixs: Instruction[] = [];
  let ata: Address;
  let createAtaIxs: Instruction[];
  if (wsolTa) {
    ata = wsolTa;
    createAtaIxs = [];
  } else {
    const ataInfo = await createAtaIdempotent(
      params.executor,
      createNoopSigner(params.executor),
      WRAPPED_SOL_MINT,
      TOKEN_PROGRAM_ADDRESS,
    );
    ata = ataInfo.ata;
    createAtaIxs = [ataInfo.createAtaIx];
  }
  ixs.push(...createAtaIxs);
  if (withDeposit && params.amount) {
    ixs.push(...getDepositWsolIxs(createNoopSigner(params.executor), ata, params.amount));
  }

  return ixs;
}

/**
 * Get the deposit WSOL instructions
 * @param owner - the owner address
 * @param ata - the ata address
 * @param amountLamports - the amount in lamports
 * @returns the transaction instructions
 */
export function getDepositWsolIxs(owner: TransactionSigner, ata: Address, amountLamports: BN): Instruction[] {
  const ixns: Instruction[] = [];

  // Transfer to WSOL ata
  ixns.push(
    getTransferSolInstruction({
      source: owner,
      destination: ata,
      amount: BigInt(amountLamports.toString()),
    }),
  );

  // Sync wrapped SOL
  ixns.push(
    getSyncNativeInstruction(
      { account: ata },
      {
        programAddress: TOKEN_PROGRAM_ADDRESS,
      },
    ),
  );

  return ixns;
}

export async function getInitOutputAtaIxs(params: RouteParams, ctx: IRouterContext): Promise<Instruction[]> {
  if (
    params.destinationTokenAccount !== undefined ||
    params.includeSetupIxs === false ||
    (params.tokenOut === WRAPPED_SOL_MINT && params.wrapAndUnwrapSol)
  ) {
    // we assume that the wrap and unwrap ixs handle the WSOL ata creation
    return [];
  } else {
    const [_, initOutAtaIx] = await createAssociatedTokenAccountIdempotentInstruction(
      params.executor,
      params.tokenOut,
      createNoopSigner(params.executor),
      ctx.outMintInfo.tokenProgramId,
    );
    return [initOutAtaIx];
  }
}

export function isRequestedRouterType(requestedFilterArray: string[], routerType: string): boolean {
  return requestedFilterArray.length == 0 || requestedFilterArray.includes(routerType);
}

export function filterArrayRouterTypes(routerTypes: RouterType[] | undefined, includeRfq: boolean): string[] {
  // Handle the case when no router types are specified - use all routers
  const filterArray = !routerTypes || routerTypes.length === 0 ? [...SUPPORTED_ROUTER_TYPES] : routerTypes;

  if (!includeRfq) {
    // Remove RFQ routers from the filter array
    return filterArray.filter((routerType) => !RFQ_ROUTERS.includes(routerType));
  }

  // Filter out invalid router types (should already be validated at controller level)
  return filterArray;
}

export function safeBNToNumber(value: BN): number {
  return new Decimal(value.toString()).toNumber();
}
